"""
Simple in-memory SQL database engine.

Supports:
  CREATE TABLE name (col1 TYPE, col2 TYPE, ...)
  INSERT INTO name VALUES (val1, val2, ...)
  SELECT [DISTINCT] cols FROM name
      [WHERE condition]
      [GROUP BY col]
      [ORDER BY col [ASC|DESC]]
      [LIMIT n]

Supported types: INTEGER, TEXT, REAL
Aggregates: COUNT(*), COUNT(col), SUM(col), AVG(col)
WHERE supports: =, !=, <, >, <=, >=, AND, OR
"""

import re


class Table:
    def __init__(self, name, columns):
        self.name = name
        self.columns = columns    # list of (col_name, col_type)
        self.rows = []


class Database:
    def __init__(self):
        self.tables = {}


class SQLEngine:
    """Parses and executes a subset of SQL.

    Return formats:
      CREATE/INSERT: string message or {"error": "..."}
      SELECT: {"columns": ["col1", ...], "rows": [[val1, ...], ...]}
    """

    VALID_TYPES = {"INTEGER", "TEXT", "REAL"}

    def __init__(self):
        self.db = Database()

    def execute(self, sql):
        sql = sql.strip().rstrip(';').strip()
        if not sql:
            return {"error": "empty statement"}
        upper = sql.upper()
        if upper.startswith("CREATE"):
            return self._execute_create(sql)
        elif upper.startswith("INSERT"):
            return self._execute_insert(sql)
        elif upper.startswith("SELECT"):
            return self._execute_select(sql)
        else:
            return {"error": "unknown statement type"}

    # ---------------- CREATE ----------------
    def _execute_create(self, sql):
        m = re.match(r'(?is)^CREATE\s+TABLE\s+([A-Za-z_][A-Za-z0-9_]*)\s*\((.*)\)\s*$', sql)
        if not m:
            return {"error": "invalid CREATE TABLE syntax"}
        name = m.group(1)
        cols_def = m.group(2).strip()
        if not cols_def:
            return {"error": "table must have at least one column"}
        if name in self.db.tables:
            return {"error": "table '%s' already exists" % name}
        columns = []
        seen = set()
        for part in cols_def.split(','):
            part = part.strip()
            cm = re.match(r'^([A-Za-z_][A-Za-z0-9_]*)\s+([A-Za-z]+)$', part)
            if not cm:
                return {"error": "invalid column definition: '%s'" % part}
            col_name, col_type = cm.group(1), cm.group(2).upper()
            if col_type not in self.VALID_TYPES:
                return {"error": "unsupported type '%s'" % col_type}
            if col_name in seen:
                return {"error": "duplicate column '%s'" % col_name}
            seen.add(col_name)
            columns.append((col_name, col_type))
        self.db.tables[name] = Table(name, columns)
        return "Table '%s' created" % name

    # ---------------- INSERT ----------------
    def _parse_literal(self, tok):
        tok = tok.strip()
        if len(tok) >= 2 and tok[0] == "'" and tok[-1] == "'":
            return tok[1:-1].replace("''", "'")
        if len(tok) >= 2 and tok[0] == '"' and tok[-1] == '"':
            return tok[1:-1].replace('""', '"')
        if tok.upper() == 'NULL':
            return None
        try:
            return int(tok)
        except ValueError:
            pass
        try:
            return float(tok)
        except ValueError:
            pass
        return {"error": "invalid value '%s'" % tok}

    def _split_values(self, s):
        parts, depth, cur, in_str, q = [], 0, [], False, None
        for ch in s:
            if in_str:
                cur.append(ch)
                if ch == q:
                    in_str = False
            elif ch in ("'", '"'):
                in_str = True
                q = ch
                cur.append(ch)
            elif ch == '(':
                depth += 1
                cur.append(ch)
            elif ch == ')':
                depth -= 1
                cur.append(ch)
            elif ch == ',' and depth == 0:
                parts.append(''.join(cur))
                cur = []
            else:
                cur.append(ch)
        parts.append(''.join(cur))
        return parts

    def _execute_insert(self, sql):
        m = re.match(r'(?is)^INSERT\s+INTO\s+([A-Za-z_][A-Za-z0-9_]*)\s+VALUES\s*\((.*)\)\s*$', sql)
        if not m:
            return {"error": "invalid INSERT syntax"}
        name = m.group(1)
        if name not in self.db.tables:
            return {"error": "unknown table '%s'" % name}
        table = self.db.tables[name]
        raw_vals = self._split_values(m.group(2))
        if len(raw_vals) != len(table.columns):
            return {"error": "expected %d values, got %d" % (len(table.columns), len(raw_vals))}
        row = []
        for tok, (cname, ctype) in zip(raw_vals, table.columns):
            val = self._parse_literal(tok)
            if isinstance(val, dict):
                return val
            if val is not None:
                if ctype == "INTEGER" and not (isinstance(val, int) and not isinstance(val, bool)):
                    return {"error": "type mismatch for column '%s'" % cname}
                if ctype == "REAL" and not isinstance(val, (int, float)):
                    return {"error": "type mismatch for column '%s'" % cname}
                if ctype == "TEXT" and not isinstance(val, str):
                    val = str(val)
            row.append(val)
        table.rows.append(row)
        return "1 row inserted into '%s'" % name

    # ---------------- SELECT ----------------
    def _tokenize_where(self, s):
        token_re = re.compile(r"""
            (\s+)
          | (<=|>=|!=|=|<|>)
          | (\(|\))
          | ('(?:[^']|'')*')
          | ([A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)?)
          | (-?\d+\.\d+|-?\d+)
        """, re.VERBOSE)
        tokens = []
        pos = 0
        while pos < len(s):
            m = token_re.match(s, pos)
            if not m:
                return None
            if m.group(1) is None:
                tokens.append(next(g for g in m.groups()[1:] if g is not None))
            pos = m.end()
        return tokens

    def _execute_select(self, sql):
        m = re.match(r'(?is)^SELECT\s+(DISTINCT\s+)?(.+?)\s+FROM\s+([A-Za-z_][A-Za-z0-9_]*)\s*(.*)$', sql)
        if not m:
            return {"error": "invalid SELECT syntax"}
        distinct = bool(m.group(1))
        cols_str = m.group(2).strip()
        table_name = m.group(3)
        rest = m.group(4).strip()

        if table_name not in self.db.tables:
            return {"error": "unknown table '%s'" % table_name}
        table = self.db.tables[table_name]
        col_names = [c[0] for c in table.columns]

        # Parse clauses: WHERE, GROUP BY, ORDER BY, LIMIT
        where_str = group_str = order_str = limit_str = None
        cm = re.search(r'(?is)\bWHERE\b', rest)
        if rest:
            # find keyword positions
            kw_positions = []
            for kw in ('WHERE', 'GROUP\s+BY', 'ORDER\s+BY', 'LIMIT'):
                km = re.search(r'(?is)\b' + kw + r'\b', rest)
                if km:
                    kw_positions.append((km.start(), km.end(), kw))
            kw_positions.sort()
            if kw_positions:
                first = kw_positions[0]
                if rest[:first[0]].strip():
                    return {"error": "invalid SELECT syntax"}
                segs = []
                for i, (st, en, kw) in enumerate(kw_positions):
                    end = kw_positions[i+1][0] if i+1 < len(kw_positions) else len(rest)
                    segs.append((kw, rest[en:end].strip()))
                for kw, val in segs:
                    if kw == 'WHERE':
                        where_str = val
                    elif kw == 'GROUP\s+BY':
                        group_str = val
                    elif kw == 'ORDER\s+BY':
                        order_str = val
                    elif kw == 'LIMIT':
                        limit_str = val
        del cm

        limit_n = None
        if limit_str is not None:
            try:
                limit_n = int(limit_str)
                if limit_n < 0:
                    raise ValueError
            except ValueError:
                return {"error": "invalid LIMIT value"}

        # ORDER BY
        order_col, order_desc = None, False
        if order_str is not None:
            om = re.match(r'(?is)^([A-Za-z_][A-Za-z0-9_]*)\s*(ASC|DESC)?$', order_str)
            if not om:
                return {"error": "invalid ORDER BY clause"}
            order_col = om.group(1)
            order_desc = (om.group(2) or '').upper() == 'DESC'
            if order_col not in col_names:
                return {"error": "unknown column '%s'" % order_col}

        # GROUP BY
        group_col = None
        if group_str is not None:
            group_col = group_str.strip()
            if group_col not in col_names:
                return {"error": "unknown column '%s'" % group_col}

        # Parse select items
        agg_re = re.compile(r'(?is)^(COUNT|SUM|AVG)\s*\(\s*(\*|[A-Za-z_][A-Za-z0-9_]*)\s*\)$')
        select_items = []  # ('col', name) or ('agg', func, arg)
        has_agg = False
        if cols_str == '*':
            select_items = [('col', c) for c in col_names]
        else:
            for part in self._split_values(cols_str):
                part = part.strip()
                am = agg_re.match(part)
                if am:
                    func, arg = am.group(1).upper(), am.group(2)
                    if arg != '*' and arg not in col_names:
                        return {"error": "unknown column '%s'" % arg}
                    select_items.append(('agg', func, arg))
                    has_agg = True
                else:
                    if part not in col_names:
                        return {"error": "unknown column '%s'" % part}
                    select_items.append(('col', part))
        if group_col and not has_agg:
            # plain group by without aggregates is allowed; treat as grouping
            pass

        # WHERE evaluation
        def get_val(row, col):
            try:
                return row[col_names.index(col)]
            except ValueError:
                return ("__ERROR__", col)

        def compare(a, op, b):
            if a is None or b is None:
                return False
            if op == '=':
                return a == b
            if op == '!=':
                return a != b
            try:
                if op == '<':
                    return a < b
                if op == '>':
                    return a > b
                if op == '<=':
                    return a <= b
                if op == '>=':
                    return a >= b
            except TypeError:
                return False
            return False

        def eval_where(row):
            if where_str is None:
                return True, None
            tokens = self._tokenize_where(where_str)
            if tokens is None:
                return None, "invalid WHERE clause"
            pos = [0]

            def parse_or():
                val, err = parse_and()
                if err:
                    return val, err
                while pos[0] < len(tokens) and tokens[pos[0]].upper() == 'OR':
                    pos[0] += 1
                    rhs, err = parse_and()
                    if err:
                        return None, err
                    val = val or rhs
                return val, None

            def parse_and():
                val, err = parse_factor()
                if err:
                    return val, err
                while pos[0] < len(tokens) and tokens[pos[0]].upper() == 'AND':
                    pos[0] += 1
                    rhs, err = parse_factor()
                    if err:
                        return None, err
                    val = val and rhs
                return val, None

            def parse_factor():
                if pos[0] >= len(tokens):
                    return None, "invalid WHERE clause"
                tok = tokens[pos[0]]
                if tok == '(':
                    pos[0] += 1
                    val, err = parse_or()
                    if err:
                        return None, err
                    if pos[0] >= len(tokens) or tokens[pos[0]] != ')':
                        return None, "invalid WHERE clause"
                    pos[0] += 1
                    return val, None
                # operand op operand
                left = tok
                pos[0] += 1
                if pos[0] >= len(tokens) or tokens[pos[0]] not in ('=', '!=', '<', '>', '<=', '>='):
                    return None, "invalid WHERE clause"
                op = tokens[pos[0]]
                pos[0] += 1
                if pos[0] >= len(tokens):
                    return None, "invalid WHERE clause"
                right = tokens[pos[0]]
                pos[0] += 1
                lv, lerr = resolve(left)
                if lerr:
                    return None, lerr
                rv, rerr = resolve(right)
                if rerr:
                    return None, rerr
                return compare(lv, op, rv), None

            def resolve(tok):
                if re.match(r'^[A-Za-z_]', tok) and not tok.startswith("'"):
                    if tok.upper() == 'NULL':
                        return None, None
                    v = get_val(row, tok)
                        if isinstance(v, tuple) and v and v[0] == "__ERROR__":
                        return None, "unknown column '%s'" % tok
                    return v, None
                if tok.startswith("'"):
                    return tok[1:-1].replace("''", "'"), None
                if '.' in tok:
                    return float(tok), None
                return int(tok), None

            val, err = parse_or()
            if err:
                return None, err
            if pos[0] != len(tokens):
                return None, "invalid WHERE clause"
            return val, None

        filtered = []
        for row in table.rows:
            ok, err = eval_where(row)
            if err:
                return {"error": err}
            if ok:
                filtered.append(row)

        # Aggregation / grouping
        def compute_agg(func, arg, rows):
            vals = []
            if arg == '*':
                vals = [1 for _ in rows]
            else:
                idx = col_names.index(arg)
                vals = [r[idx] for r in rows if r[idx] is not None]
            if func == 'COUNT':
                return len(rows) if arg == '*' else len(vals)
            if not vals:
                return None
            try:
                if func == 'SUM':
                    return sum(vals)
                if func == 'AVG':
                    return sum(vals) / len(vals)
            except TypeError:
                return {"error": "non-numeric column in aggregate"}
            return None

        out_columns = []
        for item in select_items:
            if item[0] == 'col':
                out_columns.append(item[1])
            else:
                out_columns.append("%s(%s)" % (item[1], item[2]))

        out_rows = []
        if has_agg or group_col:
            if group_col:
                groups = {}
                order = []
                gidx = col_names.index(group_col)
                for r in filtered:
                    key = r[gidx]
                    if key not in groups:
                        groups[key] = []
                        order.append(key)
                    groups[key].append(r)
                for key in order:
                    grows = groups[key]
                    out_row = []
                    for item in select_items:
                        if item[0] == 'col':
                            idx = col_names.index(item[1])
                            out_row.append(grows[0][idx])
                        else:
                            v = compute_agg(item[1], item[2], grows)
                            if isinstance(v, dict):
                                return v
                            out_row.append(v)
                    out_rows.append(out_row)
            else:
                out_row = []
                for item in select_items:
                    if item[0] == 'col':
                        idx = col_names.index(item[1])
                        out_row.append(filtered[0][idx] if filtered else None)
                    else:
                        v = compute_agg(item[1], item[2], filtered)
                        if isinstance(v, dict):
                            return v
                        out_row.append(v)
                out_rows.append(out_row)
        else:
            for r in filtered:
                out_row = []
                for item in select_items:
                    idx = col_names.index(item[1])
                    out_row.append(r[idx])
                out_rows.append(out_row)

        # DISTINCT
        if distinct:
            seen = set()
            new_rows = []
            for r in out_rows:
                key = tuple(r)
                if key not in seen:
                    seen.add(key)
                    new_rows.append(r)
            out_rows = new_rows

        # ORDER BY
        if order_col:
            if order_col in out_columns:
                oidx = out_columns.index(order_col)
            else:
                oidx = None
                base_idx = col_names.index(order_col)
            if oidx is not None:
                def sort_key(r, idx=oidx):
                    v = r[idx]
                    return (v is None, v)
                try:
                    out_rows.sort(key=sort_key, reverse=order_desc)
                except TypeError:
                    pass
            else:
                # order by column not in output: sort filtered rows before projection
                pass

        # LIMIT
        if limit_n is not None:
            out_rows = out_rows[:limit_n]

        return {"columns": out_columns, "rows": out_rows}
EOF
